  "peseshet|passive|0": {"name": "烛焰盛", "info": "若自身生命值高于50%，攻击速度提升。", "detail": "若自身生命值高于50%，赋予自身攻击速度<color=#C8B450>{BUFF:buffEffectAdjust+19}%</color>。"},
