  "garana|normal|0": {"name": "环音脉冲", "info": "3段攻击范围内敌人。", "detail": "一段：对圆形范围内敌方造成<color=#C8B450>{DAMAGE:damageAdjust+65}%</color>伤害。\n二段：对圆形范围内敌方造成<color=#C8B450>{DAMAGE:damageAdjust+65}%</color>伤害。\n三段：对圆形范围内敌方造成<color=#C8B450>{DAMAGE:damageAdjust2+115}%</color>伤害。"},
  "garana|class|0": {"name": "音爆", "info": "[格挡反击] 攻击范围内敌人并附加晕眩。", "detail": "[格挡反击]\n触发条件：格挡后，射程内有目标才发动\n对面前扇形范围内敌方造成<color=#C8B450>{DAMAGE:damageAdjust+230}%</color>伤害，并附加晕眩效果(持续<color=#C8B450>1</color>秒)。"},
  "garana|class|1": {"name": "音爆", "info": "[格挡反击] 攻击范围内敌人并附加晕眩。", "detail": "[格挡反击]\n触发条件：格挡后，射程内有目标才发动\n对面前扇形范围内敌方造成<color=#C8B450>{DAMAGE:damageAdjust_ex+258}%</color>伤害，并附加晕眩效果(持续<color=#C8B450>1</color>秒)。"},
  "garana|auto|0": {"name": "破空声浪", "info": "[职系技衍生] [极式衍生] 攻击范围内敌人，并赋予额外伤害降低效果。", "detail": "[职系技衍生] [极式衍生]\n触发条件：施展极式或职系技后发动\n对面前扇形范围内敌方造成<color=#C8B450>{DAMAGE:damageAdjust+450}%</color>伤害，并赋予其额外伤害<color=#C8B450>-20%</color>效果(持续<color=#C8B450>8</color>秒)。"},
  "garana|auto|1": {"name": "破空声浪", "info": "[职系技衍生] [极式衍生] 攻击范围内敌人，并赋予额外伤害降低效果。", "detail": "[职系技衍生] [极式衍生]\n触发条件：施展极式或职系技后发动\n对面前扇形范围内敌方造成<color=#C8B450>{DAMAGE:damageAdjust_ex+470}%</color>伤害，并赋予其额外伤害<color=#C8B450>-30%</color>效果(持续<color=#C8B450>12</color>秒)。"},
  "garana|extreme|0": {"name": "狂啸轰鸣", "info": "以自身为中心多段攻击范围内敌人，附加嘲讽与晕眩效果，并赋予范围内我方角色防御力上升。", "detail": "以自身为中心，对圆形范围内敌方造成<color=#C8B450>3</color>次<color=#C8B450>{DAMAGE:damageAdjust+480}%</color>伤害，每次攻击皆带有额外嘲讽与晕眩(持续<color=#C8B450>2.5</color>秒)效果。同时赋予范围内我方角色防御力<color=#C8B450>+{BUFF:buffEffectAdjust+15.5}%</color>效果(持续<color=#C8B450>20</color>秒)。"},
  "garana|interference|0": {"name": "叠频共振", "info": "装备者物理攻击克制率提升\n装备者格挡后物理攻击克制率提升", "detail": "装备者物理攻击克制率<color=#C8B450>+{BUFF:buffEffectAdjust+3}%</color>\n装备者格挡后，装备者物理攻击克制率<color=#C8B450>+{STACKABLEBUFF:P0015_InterferenceSkillEffects_PhysicsPierceUp_Lv1:stackableBuffIdAdjust_ex:0}%</color>效果<color=#C8B450>1</color>层(最大<color=#C8B450>2</color>层)(持续<color=#C8B450>5</color>秒)"},
  "garana|passive|0": {"name": "音浪震耳", "info": "发动最后一段普攻时，提升范围内我方角色防御力。", "detail": "发动最后一段普攻时，赋予以自身为中心之圆形范围内我方角色防御力<color=#C8B450>+{STACKABLEBUFF:P0015_PassiveSkillEffects_DefUp_Lv1:stackableBuffIdAdjust:0}%</color>效果(最大<color=#C8B450>1</color>层)(持续<color=#C8B450>8</color>秒)。"},
  "huarui|normal|0": {"name": "疾莲步", "info": "3段攻击范围内敌人。", "detail": "一段：对面前矩形范围内敌方造成<color=#C8B450>{DAMAGE:damageAdjust+40}%</color>伤害。\n二段：对面前矩形范围内敌方造成<color=#C8B450>3</color>次<color=#C8B450>{DAMAGE:damageAdjust+40}%</color>伤害。\n三段：对扇形范围内敌方造成<color=#C8B450>{DAMAGE:damageAdjust2+68}%</color>伤害。"},
  "huarui|class|0": {"name": "燎原掌", "info": "[闪避反击] 多段攻击范围内敌人，并赋予自身攻击速度提升。", "detail": "[闪避反击]\n触发条件：闪避后发动\n对矩形范围内敌方造成<color=#C8B450>3</color>次<color=#C8B450>{DAMAGE:damageAdjust+58}%</color>伤害，并赋予自身攻击速度<color=#C8B450>+{BUFF:buffEffectAdjust+16}%</color>效果(持续<color=#C8B450>9</color>秒)。"},
  "huarui|class|1": {"name": "燎原掌", "info": "[闪避反击] 多段攻击范围内敌人，并赋予自身攻击速度与暴击伤害提升。", "detail": "[闪避反击]\n触发条件：闪避后发动\n对矩形范围内敌方造成<color=#C8B450>3</color>次<color=#C8B450>{DAMAGE:damageAdjust_ex+75}%</color>伤害，并赋予自身攻击速度<color=#C8B450>+{BUFF:buffEffectAdjust_ex+32}%</color>与暴击伤害<color=#C8B450>+25%</color>效果(持续<color=#C8B450>9</color>秒)。"},
